Method.Source:
    /// <summary>
    /// Class entry point. The system will call this method when a designated menu 
    /// is selected or when execution starts and this class is set as the startup class.
    /// </summary>
    /// <param name = "_args">The specified arguments.</param>
    public static void main(Args _args)
    {
        METGUPPriceAPI_Test instance = new METGUPPriceAPI_Test();
        instance.run();

        Info("Finished");
    }

    public void run()
    {
        GUPParameters                   gupParameters = gupParameters::find();
        EcoResAttribute                 attributes = EcoResAttribute::find(gupParameters.METSalesEventAttribute);
        EcoResAttributeType             attributeType = EcoResAttributeType::find(attributes.AttributeType);

        InventDim inventDim;
        inventDim.clear();
        inventDim.InventSiteId = "CANNGVFOOD";

        inventDim = inventDim::findOrCreate(inventDim);

        AccountNum  custAccount = "64100013";
        InventSiteId custSiteId = "CANNGVFOOD";
        InventDimId inventDimId = inventDim.inventDimId;
        ItemId      itemId      = "109854";
        Qty         qty         = 1;
        SalesUnit   salesUnit   = "EA";
        guid        sessionGuid = newGuid();
        METEventId  eventId     = ""; //"Easter";

        GUPTmpPriceReportValues priceReportValues;

        utcdatetime             dateTimeNow = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimezone());
        System.DateTimeOffset   dateTimeOffset  = new System.DateTimeOffset(dateTimeNow, System.TimeSpan::Zero);
       
        GUPPricingAttributeHelper   pricingAttributeHelper = new GUPPricingAttributeHelper();
        GUPRetailPriceCheck         retailPriceCheck    = RetailPricingCalculatorCreator::getInstance().createPriceCheck();
        List                        priceDiscountLines  = new List(Types::Class);
        RetailPriceDiscountLine     priceDiscountLine   = new RetailPriceDiscountLine();

        retailPriceCheck.parmReportId(sessionGuid);
        retailPriceCheck.parmCustAccount(CustAccount);
        retailPriceCheck.parmPricingAttributeHelper(pricingAttributeHelper);

        priceDiscountLine.parmInventDimId(inventDimId);
        priceDiscountLine.parmCatalogRefRecId(0);
        priceDiscountLine.parmReferenceRecId(0);
        priceDiscountLine.parmItemId(itemId);
        priceDiscountLine.parmQty(qty);
        priceDiscountLine.parmSalesUnit(salesUnit);
        
        priceDiscountLines.addEnd(priceDiscountLine);

        retailPriceCheck.setSalesOrderAttributeByClassId(classNum(GUPPricingAttributeEcoResAttribute),              //class Id
                                                        eventId,                                                    // value of attribute
                                                        classNum(GUPPricingAttributeProviderSalesTableAttribute),   //attribute provider class Id
                                                        attributes.Name,                                            // attribute name
                                                        attributeType.Name);                                        //attribute type

        retailPriceCheck.calculatePriceDiscountsWithDateTime(priceDiscountLines, dateTimeOffset);

        while select priceReportValues
            where priceReportValues.ReportId == sessionGuid
        {
            Info(strFmt("Jubii! %1", guid2Str(sessionGuid)));
        }
    }
